export function portraitMeta(src:string){if(simulationPortraits[src])return {...simulationPortraits[src],label:'시뮬레이션 캐릭터 이미지'};const index=characterCovers.indexOf(src);const positions=['50% 24%','50% 12%','50% 12%','50% 14%','50% 18%','50% 26%','50% 18%','50% 21%','50% 14%','50% 14%','50% 23%','50% 15%','50% 21%','50% 14%','50% 20%','50% 20%','50% 8%','50% 20%','50% 12%','50% 24%','50% 9%','50% 13%','50% 8%','50% 8%','50% 17%','50% 23%','50% 50%','50% 16%','50% 18%'];const dimensions=index===28?[1104,1824]:index===27?[768,1280]:index===26?[768,960]:(index===3||(index>=20&&index<=23))?[768,1280]:[7,9,13,14,15,16,17,18,19,24,25].includes(index)?[1104,1824]:[10,11,12].includes(index)?[1536,2048]:[1248,1600];return {width:index<0?1024:dimensions[0],height:index<0?1536:dimensions[1],position:index<0?'50% 24%':positions[index],label:index===26?'슬라임 캐릭터 · 이미지 준비 중':index<0?'기존 작품 이미지':(sampleWorks.find(w=>w.cover===src)?.characters[0]?.name||'캐릭터 '+(index+1))+' 일러스트'};}
export const blankWork=():Work=>({id:'',rating:'19+',title:'',tag:'일상',desc:'',world:'',secret:'',characters:[{name:'',age:25,role:'',personality:''}],openings:[{title:'첫 만남',text:'',suggestions:[]}],cover:covers[1],status:'draft'});

export function workRating(w:Work):'19+'|'all'{return w.id==='sample-sori'||w.id==='sample-slime'||w.cover===characterCovers[0]||w.cover===characterCovers[26]?'all':w.rating||'19+';}
export function normalizedWork(w:Work):Work{return {...w,creatorGuide:w.creatorGuide||sampleWorks.find(sample=>sample.id===w.id)?.creatorGuide,rating:workRating(w),characters:w.characters.map((c,i)=>({...c,id:c.id||`${w.id}-character-${i}`}))};}
/** Mark narration in authored seed openings only. Never guess roles in user-written prose. */
export function sampleNarration(text:string){
 if(text.includes('*'))return text;
 return text.split(/(“[^”]*”|‘[^’]*’|「[^」]*」|"[^"\n]*"|'[^'\n]*')/g).map(part=>
  !part.trim()||/^[“‘「"']/.test(part)?part:part.replace(/([^\n]+)/g,line=>line.trim()?`*${line}*`:line)
 ).join('');
}
// Reproduce the old seed formatter solely to recognize already-stored demo text.
function previousSampleNarration(text:string){if(text.includes('*'))return text;return text.split(/(“[^”]*”|「[^」]*」)/g).map(s=>!s.trim()||s.startsWith('“')||s.startsWith('「')?s:s.replace(/([^\n]+)/g,part=>part.trim()?`*${part}*`:part)).join('');}
const knownSampleDisplays=new Map<string,Map<string,string>>();
for(const w of [...sampleWorks,...legacySampleWorks]){
 const known=new Map<string,string>();
 for(const o of w.openings){const formatted=sampleNarration(o.text);known.set(o.text,formatted);known.set(previousSampleNarration(o.text),formatted);known.set(formatted,formatted);}
 // Unquoted, handwritten sample replies are spoken dialogue, not narration.
 for(const reply of w.sampleReplies||[]){known.set(reply,reply);known.set(previousSampleNarration(reply),reply);}
 knownSampleDisplays.set(w.id,known);
 w.rating=workRating(w);w.characters=w.characters.map((c,i)=>({...c,id:c.id||`${w.id}-character-${i}`}));
 w.openings=w.openings.map(o=>({...o,text:sampleNarration(o.text)}));
}
for(const previous of previousSeedDialogue){const known=knownSampleDisplays.get(previous.id)||new Map<string,string>();for(const text of previous.openings){const formatted=sampleNarration(text);known.set(text,formatted);known.set(previousSampleNarration(text),formatted);known.set(formatted,formatted);}for(const text of previous.replies){known.set(text,text);known.set(previousSampleNarration(text),text);}knownSampleDisplays.set(previous.id,known);}
/** Display-only compatibility for exact known assistant demo strings. No DB mutation. */
export function knownAssistantDisplay(work:Work,text:string):string{
 const known=knownSampleDisplays.get(work.id);if(known?.has(text))return known.get(text)!;
 const name=work.characters[0]?.name;
 if(!name)return text;
 const fallbacks=[`${name}은 잠시 생각에 잠겼다가 고개를 끄덕였다.\n\n“그 이야기는 조금 더 듣고 싶어요. 지금 가장 궁금한 건 무엇인가요?”`,`조용한 공기 사이로 ${name}의 목소리가 들렸다.\n\n“서두르지 않아도 괜찮아요. 우리에게는 아직 시간이 있으니까.”`,`“그럼, 여기서부터 시작해 볼까요?”\n\n${name}이 당신을 바라보며 작은 미소를 지었다.`];
 for(const raw of fallbacks)if(text===raw||text===previousSampleNarration(raw))return sampleNarration(raw);
 return text;
}

export const defaultRules=():ResponseRules=>({ooc:'',style:'대사 → 지문 네 문장 안팎 → 대사 → 지문 두세 문장의 호흡으로 쓴다. 지문은 *별표*로 감싸 별도 문단에 두되, 문장마다 줄바꿈하지 않고 한 문단의 줄글로 이어 쓴다. 말투, 손짓, 시선, 주변 소리와 장면의 작은 변화를 구체적으로 묘사한다. 분량을 채우기 위한 반복과 상투적인 감정 해설은 피한다. 사용자의 직전 말에 반응하고 다음 행동을 선택할 여지를 남긴다. 사용자의 행동이나 감정을 대신 확정하지 않는다. 사용자가 짧은 답변을 요청하면 그 요청을 따른다.',length:'balanced',perspective:'캐릭터 중심. 사용자의 행동과 감정을 대신 결정하지 않기'});
export function publicWork(w:Work):Work{const {secret,responseRules,...rest}=normalizedWork(w);return rest as Work;}

export function workAuthor(w:Work){return w.id.startsWith('sample-')?'익명':w.authorName||'나';}

/** Legacy author-written descriptions remain untouched. New cards have an explicit short hook. */
export function workHook(w:Work){return w.hook?.trim()||w.desc;}

const conciseSampleReplies:Record<string,string[]>={"sample-sori":["“유력한 가설이야! …라고 쓰고, 틀리면 같이 지우자.”","“오늘 사건 없으면? 그냥 만나면 되지. 수첩 없이도 친구는 친구니까.”"],"sample-silver":["“당신이 싫다는 말과, 당신의 의견이 필요하다는 말은 양립합니다.”","“오늘은 조약 때문이 아닙니다. 조금 더 함께 걷고 싶어서 붙잡았어요. 가셔도 됩니다.”"],"sample-suit":["“그때의 저는 당신보다 제 판단을 믿었습니다. 그 책임까지 미래 탓으로 돌리진 않겠습니다.”","“명령… 아니, 부탁입니다. 오늘 저녁은 업무가 끝난 뒤에 물어보겠습니다.”"],"sample-warm":["“우리가 예전에 친했다는 건 좋은 시작이지, 지금도 뭐든 안다는 뜻은 아니잖아요.”","“당신 때문에 보이는 색도 좋지만, 오늘은 내가 좋아하는 바다를 보여주고 싶었어요.”"],"sample-ruby":["“책에 내가 나쁜 사람이라고 쓰였나요? 그렇다면 오늘 일은 직접 써요.”","“먼저 발견한 건 나예요. 함께 돌아온 건 우리고. 지도에는 둘 다 적어야죠.”"],"sample-violet":["“좋았다는 말보다 어디서 안 들렸는지가 필요해요. 다시 부를 수 있으니까.”","“구해줘서 곁에 있는 건 아니에요. 다음 노래도 당신에게 먼저 들려주고 싶어서요.”"],"sample-muse":["“연기 점수는 만점인데요. 방금 웃은 건 계산에 안 넣었어요.”","“영수증에 안 적힌 말도 해볼게요. 오늘 당신이 와서 좋았어요.”"],"sample-dragon":["“배우자는 내 보물이라는 표현은 철회하지. 보물은 내 곁을 떠날지 고를 수 없으니.”","“계약이 끝난 뒤에도 자리는 비워둘 생각이다. 오라는 명령이 아니라, 그대에게만 하는 초대다.”"],"sample-succubus":["“더 만나고 싶은 마음은 제 거예요. 그러니까 당신 일정을 대신 정할 핑계로 쓰면 안 되겠죠.”","“꿈에서 고른 완벽한 답 말고요. 오늘 실제로 제가 한 일을 기억해주면 좋겠어요.”"],"sample-gumiho":["“그리웠다는 말과 무죄라는 주장은 따로 하겠습니다. 어느 쪽도 다른 쪽의 증거는 아니니까요.”","“이번엔 사라지지 않겠다고 약속하기보다, 어디로 가는지 먼저 말할게요.”"],"sample-serpent":["“명령을 고친다고 약원이 무너지지는 않겠지요. 잘못된 명령을 지키면 무너질 수도 있고.”","“오늘은 업무 보고가 아닙니다. 그대가 본 바깥의 봄이 궁금해서 부른 거예요.”"],"sample-ram-demon":["“지난밤의 제가 좋아했다는 이유만으로 오늘의 제가 약속한 건 아니죠. 대신 다시 들려줄래요?”","“다들 잘 보내드렸으니까, 이번엔 저도 출발 안내를 받아보고 싶네요.”"],"sample-cold-editor":["“미래를 봤다는 말은 제 주장이고, 이 문장을 남길 권리는 당신에게 있습니다.”","“작품에서는 지울 수 있어도 제가 한 일까지 지울 수는 없죠. 이번 사과는 제 이름으로 남기겠습니다.”"],"sample-slime":["“처음 본 색이야! 이름은 반짝초록… 아니, 네가 본 색도 먼저 들어볼게.”","“빈칸이 생겼어. 실패한 자리 말고, 다음에 같이 올 자리!”"],"sample-female-unreleased-track":["“네가 쓴 쉼표인데 왜 나만 쉬어? 이번엔 같이 멈추자. 다음 박자도 같이 세고.”","“후렴은 네 쪽이 낫네. 돌아온 이유까지 그걸로 때울 생각은 없어. 그 얘긴 앰프 끄고 하자.”"],"sample-female-anonymous-credit":["“당신한테 진 발표는 다시 봐요. 짜증이 나는데, 배울 건 또 있더라고요.”","“손목이 먼저 말해서 순서가 꼬였네요. 저는 당신을 좋아해요. 이건 제 말로 남겨 두죠.”"],"sample-female-unwritten-constellation":["“옳은 명령이었다고 믿었습니다. 믿었다는 사실까지 제 잘못에서 빼지는 않겠습니다.”","“벌을 받으러 가는 것은 어렵지 않습니다. 당신의 다음 질문 앞에 남는 것이, 제게는 더 어렵습니다.”"],"sample-female-midnight-postscript":["“좋은 문장인데 지금의 당신 같지는 않네요. 편지 속 사람하고 똑같아질 필요는 없어요.”","“오늘은 색이 안 돌아와도 괜찮습니다. 아니, 아쉽기는 하죠. 그래도 당신 말은 끝까지 듣고 싶어요.”"],"sample-female-dual-return-order":["“당신이 없으면 못 한다는 결론은 싫습니다. 함께하면 더 잘할 수 있다는 가설은 마음에 들고요.”","“지구에서 만날 확률을 계산했습니다. 제가 먼저 약속을 잡으면 훨씬 높아지더군요. 토요일 어떠세요?”"],"sample-female-storm-return-map":["“당신이 싫다는 길로 밀고 가지 않겠습니다. 다만 위험하다고 보는 이유는 끝까지 설명하겠습니다.”","“떠날 날짜는 모레 아침입니다. 목적지는 북항이고요. 이번에는 질문하지 않으셔도 먼저 말하겠습니다.”"],"sample-female-forgetful-spring":["“좋은 향이라고 말할 수는 있어요. 그래서 다가가도 된다는 뜻까지 그 말에 넣지는 않겠습니다.”","“오늘 차는 어떤가요? 저도 마시고 있습니다. 맛을 모르니까 함께 마실 이유가 없는 건 아니어서요.”"],"sample-female-final-curtain-bet":["“네 연출이 더 좋아. 이런 데서 인정하면 근사한 유언 같잖아. 나가서 한 번 더 말할 테니 기억해 둬.”","“웃기려고 한 말은 아니었어. 지금 네가 여기 있어서, 내가 혼자 결정할 수가 없다는 게 좋다는 말이야.”"],"sample-female-seasonal-engagement":["“오늘 제 편에 서 주셔서 고맙습니다. 장부에서도 제 편을 들어 달라는 부탁은 하지 않겠습니다.”","“종료일은 그대로 두었습니다. 그다음 날도 뵙고 싶다는 말까지 계약서에 넣으면, 제 부탁이 아니게 되니까요.”"],"sample-deer":["“돌아가는 길을 드렸다고, 돌아오길 바라지 않는 건 아닙니다.”","“지난번의 제가 옳았다는 증거를 찾는 일이 아닙니다. 틀린 지점을 함께 봐주십시오.”"],"sample-whitesnake":["“명령으로 듣고 싶은 답입니까, 제 답을 듣고 싶은 겁니까? 후자라면 조금만 기다려주시지요.”","“거절도 답이라고 배웠습니다. 마음에 드는 답만 골라 듣던 시절은 끝났고요.”"],"sample-dokkaebi":["“매번 내가 졌다고? 억울한데, 취향은 한결같네. 계속 너랑 놀고 싶었다는 거잖아.”","“다음 내가 또 모른 척하면 혼내도 돼. 대신 이건 기억해 줘. 지금의 나는 약속을 피하는 게 아니야.”"],"sample-crow":["“같은 이름이 적혔다고 같은 곳에 살아야 하는 건 아니야. 그래도 네가 갈 곳은 궁금해.”","“오늘도 명령을 어겼어. 후회는 없어. 설명을 늦춘 건 미안하고.”"],"sample-female-quiet-bookbinder":["“무심하다고 아무 생각 없는 건 아닙니다. 생각하고 나서 말이 늦는 쪽이죠.”","“이름은 이미 봤으니 됐고. 좋아하는 차부터 알려주세요. 그건 책에 없어서.”"],"sample-female-frail-cartographer":["“도움은 필요합니다. 제 판단까지 맡긴다는 뜻은 아니고요.”","“매칭률이 높아서 고른 여행지는 아닙니다. 당신이 그 파이를 좋아할지 궁금해서죠.”"],"sample-sim-monstergirl-dorm":["유키: “그대의 생활 시간부터 들어 보자꾸나.” 유키가 자기 찻잔을 옆으로 옮겨 회의록 놓을 자리를 만든다. “함께 사는 집이니, 누구 하나에게만 맞출 수는 없겠지.”","세라핀: “나는 해가 진 뒤에 움직여. 대신 복도에서는 조용히 할게.” 세라핀이 메모 아래에 빈칸을 남긴다. “네가 필요한 규칙도 적어.”","루비: “좋아! 그럼 무거운 짐은 나한테 맡겨.” 루비가 상자 옆에 무릎을 굽힌다. “대신… 문에 안 부딪히게 방향은 좀 봐 줘.”"],"sample-sim-sentinel-bureau":["카이엘: “조건을 먼저 말해라. 배속은 명령이지만 신뢰까지 명령할 생각은 없다.” 그가 서류를 당신 쪽으로 돌린다. “……무리하지 않겠다는 항목은 추가했으면 한다.”","시온: “숫자는 됐어. 네가 오겠다고 한 건 아니잖아.” 붉은 눈이 잠깐 내려갔다가 다시 당신을 향한다. “그래도 궁금해. 넌 여기 있고 싶어?”","루시안: “좋아요. 가장 어려운 질문부터 하시네요.” 그가 출입증을 내려놓고 손가락을 하나씩 접는다. “정보, 퇴로, 그리고 사령관님이 빼먹은 설명. 제 몫은 이 셋으로 할까요?”"],"sample-sim-villain-academy":["아드리안: 아드리안은 명부를 덮지 않고 당신 쪽으로 돌렸다. “당신 이름의 잉크만 다르지. 누가 우리보다 먼저 당신을 기다리고 있었던 모양이군.”","에델린: 에델린이 소매 끝으로 종이 가장자리를 눌렀다. “마르지도 않은 잉크예요. 추측만 하지 말고, 입교식 동안 이 방에 들어온 사람부터 확인하죠.”","이사엘: 이사엘은 문밖의 발소리에 잠시 귀를 기울였다. “복도부터 살펴보겠습니다. 혼자 남고 싶지 않다면 함께 가셔도 됩니다. 선택은 당신께 맡기겠습니다.”"]};
export function currentSampleDialogue(work:Work):Work{const current=sampleWorks.find(w=>w.id===work.id);return current&&JSON.stringify(work.sampleReplies)===JSON.stringify(conciseSampleReplies[work.id])?{...work,sampleReplies:current.sampleReplies,sampleTurns:current.sampleTurns}:work;}
